import { Platform } from 'react-native';

import { log } from '../utils/log';
import { getFeedbackPrefs, shouldPlay } from './feedbackPrefs';

export type SoundName = 'tap' | 'treat' | 'upgrade' | 'celebrate' | 'buddy-1' | 'buddy-2' | 'buddy-3' | 'sleepy' | 'new-street' | 'reward-reached' | 'walk-done';

// Generated by scripts/generateSounds.mjs. Lazy requires keep Jest (and web)
// from touching the asset pipeline just by importing this file.
const SOURCES: Record<SoundName, () => number> = {
  tap: () => require('../../assets/sounds/tap.wav'),
  treat: () => require('../../assets/sounds/treat.wav'),
  upgrade: () => require('../../assets/sounds/upgrade.wav'),
  celebrate: () => require('../../assets/sounds/celebrate.wav'),
  'buddy-1': () => require('../../assets/sounds/buddy-1.wav'),
  'buddy-2': () => require('../../assets/sounds/buddy-2.wav'),
  'buddy-3': () => require('../../assets/sounds/buddy-3.wav'),
  sleepy: () => require('../../assets/sounds/sleepy.wav'),
  'new-street': () => require('../../assets/sounds/new-street.wav'),
  'reward-reached': () => require('../../assets/sounds/reward-reached.wav'),
  'walk-done': () => require('../../assets/sounds/walk-done.wav'),
};

type AvSound = { replayAsync: () => Promise<unknown> };

const loaded: Partial<Record<SoundName, AvSound>> = {};
let audioModeSet = false;
let inFlight: Promise<void> | null = null;
let audioModeInFlight: Promise<void> | null = null;

/** Sets the shared audio mode once (also used by useAmbientMusic). Silent switch wins on iOS. */
export function ensureAudioMode(): Promise<void> {
  if (audioModeSet) return Promise.resolve();
  if (!audioModeInFlight) {
    audioModeInFlight = (async () => {
      const { Audio, InterruptionModeAndroid } = require('expo-av') as typeof import('expo-av');
      await Audio.setAudioModeAsync({
        playsInSilentModeIOS: false,
        // Walk cues must sound with the screen off / app backgrounded.
        // Android: the GPS foreground service keeps the process alive.
        // iOS caveat: this only works if Info.plist UIBackgroundModes
        // includes "audio"; the location background mode alone keeps the
        // process running but the audio session may be suspended. Check
        // app.json ios.infoPlist on a real device before relying on it.
        staysActiveInBackground: true,
        shouldDuckAndroid: false,
        interruptionModeAndroid: InterruptionModeAndroid.DoNotMix,
      });
      audioModeSet = true;
    })()
      .catch((e) => {
        log('sound', { event: 'audio-mode-failed', error: errorMessage(e) });
        throw e;
      })
      .finally(() => {
      audioModeInFlight = null;
    });
  }
  return audioModeInFlight;
}

const ALL_SOUNDS = Object.keys(SOURCES) as SoundName[];
const MAX_LOAD_ATTEMPTS = 3;
const loadAttempts: Partial<Record<SoundName, number>> = {};
let preloadLogged = false;

function errorMessage(e: unknown): string {
  return e instanceof Error ? e.message : String(e);
}

// Loads whatever is not loaded yet. Called on every play until every sound is
// in, so a sound (or the audio mode) that failed once is retried next time
// instead of a partial map being cached as final. A sound that failed
// MAX_LOAD_ATTEMPTS times is given up on so it cannot delay or spam every play.
// Every failure goes to the Debug Log. Silent switch wins on iOS.
function ensureLoaded(): Promise<void> {
  const missing = ALL_SOUNDS.filter((name) => !loaded[name] && (loadAttempts[name] ?? 0) < MAX_LOAD_ATTEMPTS);
  if (audioModeSet && missing.length === 0) return Promise.resolve();
  if (!inFlight) {
    inFlight = (async () => {
      const { Audio } = require('expo-av') as typeof import('expo-av');
      await ensureAudioMode();
      await Promise.all(
        missing.map(async (name) => {
          loadAttempts[name] = (loadAttempts[name] ?? 0) + 1;
          try {
            const { sound } = await Audio.Sound.createAsync(SOURCES[name](), { shouldPlay: false });
            loaded[name] = sound;
          } catch (e) {
            // one broken sound must not silence the rest; retried on a later play
            log('sound', { event: 'load-failed', sound: name, attempt: loadAttempts[name], error: errorMessage(e) });
          }
        })
      );
      if (!preloadLogged && ALL_SOUNDS.every((n) => loaded[n] || (loadAttempts[n] ?? 0) >= MAX_LOAD_ATTEMPTS)) {
        preloadLogged = true;
        log('sound', { event: 'preload-complete', loaded: ALL_SOUNDS.filter((n) => loaded[n]).length, total: ALL_SOUNDS.length });
      }
    })()
      .catch((e) => {
        log('sound', { event: 'preload-failed', error: errorMessage(e) });
      })
      .finally(() => {
        inFlight = null;
      });
  }
  return inFlight;
}

/** Loads every sound ahead of time (call at app start, non-blocking) so the first tap is audible. */
export function preloadSounds(): Promise<void> {
  if (Platform.OS === 'web') return Promise.resolve();
  return ensureLoaded();
}

const BUDDY_SOUNDS = ['buddy-1', 'buddy-2', 'buddy-3'] as const;
export type BuddySoundName = (typeof BUDDY_SOUNDS)[number];

/** Random Buddy cue, never the same one twice in a row. `rng` is injectable for tests. */
export function pickBuddySound(previous: BuddySoundName | null, rng: () => number = Math.random): BuddySoundName {
  const options = BUDDY_SOUNDS.filter((n) => n !== previous);
  return options[Math.min(options.length - 1, Math.floor(rng() * options.length))];
}

let lastBuddySound: BuddySoundName | null = null;

/** The "wuff-wuff" for a Buddy tap; rotates through the three motifs. */
export function playBuddy(): void {
  lastBuddySound = pickBuddySound(lastBuddySound);
  play(lastBuddySound);
}

/**
 * Fire-and-forget. No-op when sound is off or on web. Waits for the load to
 * finish before replaying, so even the very first call is audible. Failures
 * are written to the Debug Log, never thrown.
 */
export function play(name: SoundName): void {
  if (Platform.OS === 'web' || !shouldPlay(getFeedbackPrefs(), 'sound')) return;
  ensureLoaded()
    .then(() => {
      const sound = loaded[name];
      if (!sound) {
        log('sound', { event: 'play-skipped-not-loaded', sound: name });
        return undefined;
      }
      return sound.replayAsync();
    })
    .catch((e) => {
      log('sound', { event: 'play-failed', sound: name, error: errorMessage(e) });
    });
}
